import re


UNEMP_RE = re.compile(r"un\s*em\s*ploy\s*ment\s*rate|civilian\s*unemployment\s*rate", re.IGNORECASE)
PERCENT_RE = re.compile(r"\b\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\b", re.IGNORECASE)
MONTH_RE = re.compile(
    r"\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\b",
    re.IGNORECASE,
)
MONTH_YEAR_RE = re.compile(
    r"\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}\b",
    re.IGNORECASE,
)
DATE_MARKERS_RE = re.compile(
    r"\b(?:recent|latest|current|now|as of|in|during|since|stood at|fell to|rose to|edged down to|dropped to|declined to|hovered|reached|hit|was|were)\b",
    re.IGNORECASE,
)
RATE_WORDS_RE = re.compile(r"\b(?:percent|per\s*cent)\b", re.IGNORECASE)


def _normalize(text: str) -> str:
    text = text or ""
    text = re.sub(r"(\w)-\s+(\w)", r"\1\2", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _compact(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", _normalize(text).lower())


def _score_text(text: str) -> int:
    low = text.lower()
    compact = _compact(text)
    score = 0
    if "unemploymentrate" in compact or "civilianunemploymentrate" in compact:
        score += 6
    if PERCENT_RE.search(low):
        score += 4
    if MONTH_YEAR_RE.search(low):
        score += 3
    elif MONTH_RE.search(low):
        score += 2
    if DATE_MARKERS_RE.search(low):
        score += 2
    if any(tok in compact for tok in ("edgeddown", "fellt", "roset", "stoodat", "hovered", "droppedto", "declinedto", "reached", "hit", "stable")):
        score += 1
    return score


def _sentence_spans(text: str) -> list[str]:
    text = _normalize(text)
    if not text:
        return []
    chunks = re.split(r"(?<=[.!?])\s+", text)
    if len(chunks) == 1:
        return [text]
    return [chunk.strip() for chunk in chunks if chunk.strip()]


def _extract_rate_phrase(text: str) -> str | None:
    text = _normalize(text)
    if not text:
        return None
    patterns = [
        r"(?:stood at|stood|was|were)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:edged down to|fell to|dropped to|declined to|rose to|increased to|has risen to|has fallen to|has crept lower to)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:reached|peaked at|hit)\s+(?:a\s+[^,.;:]+?\s+)?(?:of\s+)?(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:from|between)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
    ]
    for pattern in patterns:
        m = re.search(pattern, text, re.IGNORECASE)
        if m:
            rate = _normalize(m.group("rate"))
            if rate:
                return rate
    matches = list(PERCENT_RE.finditer(text))
    if not matches:
        return None
    # Prefer the last percentage when the sentence describes a range or a before/after comparison.
    return _normalize(matches[-1].group(0))


def _extract_context_phrase(text: str) -> str | None:
    text = _normalize(text)
    if not text:
        return None
    patterns = [
        r"rose from\s+.*?\s+to\s+.*?\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)(?:\s+(?:in|as of)\s+[A-Za-z]+\s+\d{4})?",
        r"(?:stood at|stood|was|were)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"(?:edged down to|fell to|dropped to|declined to|rose to|increased to|has risen to|has fallen to|has crept lower to)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"(?:reached|peaked at|hit)\s+(?:a\s+[^,.;:]+?\s+)?(?:of\s+)?\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)(?:\s+(?:in|as of)\s+[A-Za-z]+\s+\d{4})?",
        r"(?:from|between)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"hovered in a narrow range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
    ]
    for pattern in patterns:
        m = re.search(pattern, text, re.IGNORECASE)
        if m:
            return _normalize(m.group(0))
    return None


def rule_unemployment_rate_recent(doc: dict) -> list[dict]:
    try:
        best_span = None
        best_score = 0
        seen = set()

        paragraphs = doc.get("paragraphs") or []
        for para in paragraphs:
            text = para.get("text") or ""
            if not text:
                continue
            compact = _compact(text)
            if "unemploymentrate" not in compact and "civilianunemploymentrate" not in compact:
                continue
            sentences = _sentence_spans(text)
            best = None
            best_score = 0
            for sent in sentences:
                score = _score_text(sent)
                if score > best_score:
                    best = sent
                    best_score = score
            if best is None:
                best = _normalize(text)
                best_score = _score_text(best)
            if best_score < 8:
                continue
            phrase = _extract_rate_phrase(best)
            context = _extract_context_phrase(best)
            if phrase and context and phrase != context:
                best_context = context
                best = phrase
            else:
                best_context = context
                if phrase:
                    best = phrase
            key = (para.get("page_no"), para.get("paragraph_no"), best)
            if key in seen:
                continue
            seen.add(key)
            if best_score > 0 and (best_span is None or best_score > best_span[0]):
                spans_to_return = []
                if best_context and best_context != best:
                    span2 = {"text": best_context}
                    if para.get("page_no") is not None:
                        span2["page_no"] = para["page_no"]
                    if para.get("paragraph_no") is not None:
                        span2["paragraph_no"] = para["paragraph_no"]
                    spans_to_return.append(span2)
                span = {"text": best}
                spans_to_return.append(span)
                best_span = (best_score, spans_to_return)

        lines = doc.get("lines") or []
        for idx, line in enumerate(lines):
            text = line.get("text") or ""
            if not text:
                continue
            compact = _compact(text)
            if "unemploymentrate" not in compact and "civilianunemploymentrate" not in compact:
                continue
            window_parts = []
            for j in range(max(0, idx - 2), min(len(lines), idx + 4)):
                part = _normalize(lines[j].get("text") or "")
                if part:
                    window_parts.append(part)
            window = " ".join(window_parts).strip()
            if not window:
                continue
            score = _score_text(window)
            if score < 8:
                continue
            phrase = _extract_rate_phrase(window)
            context = _extract_context_phrase(window)
            if phrase:
                window = phrase
            key = (line.get("page_no"), line.get("line_no"), window)
            if key in seen:
                continue
            seen.add(key)
            if best_span is None or score > best_span[0]:
                spans_to_return = []
                if context and context != window:
                    span2 = {"text": context}
                    if line.get("page_no") is not None:
                        span2["page_no"] = line["page_no"]
                    if line.get("line_no") is not None:
                        span2["line_no"] = line["line_no"]
                    spans_to_return.append(span2)
                span = {"text": window}
                spans_to_return.append(span)
                best_span = (score, spans_to_return)

        if best_span is None:
            return []
        return best_span[1]
    except Exception:
        return []

def rule_unemployment_latest_month_sentence(doc: dict) -> list[dict]:
    try:
        import re

        months = (
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        )
        month_to_num = {month.lower(): idx + 1 for idx, month in enumerate(months)}
        month_re = re.compile(r"\b(?:%s)\b" % "|".join(months), re.I)
        month_year_re = re.compile(r"\b(?:%s)\s+\d{4}\b" % "|".join(months), re.I)
        month_year_extract_re = re.compile(
            r"\b(?P<month>%s)\s+(?P<year>\d{4})\b" % "|".join(months), re.I
        )
        percent_re = re.compile(r"\b\d+(?:\.\d+)?\s*percent\b", re.I)
        unemployment_re = re.compile(
            r"\b(?:headline\s+|civilian\s+)?unemployment rate\b", re.I
        )
        verb_re = re.compile(
            r"\b(?:stood at|declined to|fell to|edged up to|ticked up to|rose to|"
            r"dipped to|remained at|held at|was)\b",
            re.I,
        )
        sentence_split_re = re.compile(r"(?<=[.!?])\s+")
        doc_name = (doc.get("doc_name") or "").lower()
        doc_year_match = re.search(r"treasury_bulletin_(\d{4})_(\d{2})", doc_name)
        doc_year = int(doc_year_match.group(1)) if doc_year_match else None

        spans = []
        seen = set()

        def add_span(text: str, meta: dict | None = None) -> None:
            cleaned = " ".join((text or "").split())
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            if meta is not None:
                if meta.get("page_no") is not None:
                    span["page_no"] = meta.get("page_no")
                if meta.get("paragraph_no") is not None:
                    span["paragraph_no"] = meta.get("paragraph_no")
                if meta.get("line_no") is not None:
                    span["line_no"] = meta.get("line_no")
            spans.append(span)

        def score_sentence(sentence: str) -> int:
            text = " ".join((sentence or "").split())
            low = text.lower()
            if "unemployment rate" not in low:
                return -1
            if not month_re.search(low):
                return -1
            if not percent_re.search(low):
                return -1
            if (
                "of those unemployed" in low
                or "share of the unemployed" in low
                or "long-term" in low
                or "27 weeks" in low
                or "broader measure" in low
            ):
                return -1

            directness = 0
            if unemployment_re.search(text):
                directness += 4
            if verb_re.search(text):
                directness += 4
            if low.startswith("the unemployment rate") or low.startswith(
                "unemployment rate"
            ):
                directness += 2
            if month_year_re.search(text):
                directness += 1
            if "headline unemployment rate" in low or "civilian unemployment rate" in low:
                directness += 1
            if "u-6" in low or "underemployment" in low:
                directness -= 5

            latest_date = 0
            first_rate_pos = low.find("unemployment rate")
            for match in month_year_extract_re.finditer(text):
                if first_rate_pos >= 0 and match.start() < first_rate_pos:
                    prefix = text[: match.start()].strip().lower()
                    if not re.search(
                        r"\b(?:in|by|as of|during|from|after|since|at|on|for)\b",
                        prefix,
                    ):
                        # Likely a page heading or page marker rather than the
                        # sentence introducing the unemployment rate.
                        continue
                month_key = match.group("month").lower()
                year = int(match.group("year"))
                latest_date = max(
                    latest_date, year * 12 + month_to_num.get(month_key, 0)
                )
            if latest_date == 0 and doc_year is not None:
                for month_match in month_re.finditer(text):
                    month_key = month_match.group(0).lower()
                    latest_date = max(
                        latest_date, doc_year * 12 + month_to_num.get(month_key, 0)
                    )

            return latest_date * 100 + directness

        paragraphs = doc.get("paragraphs") or []
        paragraph_candidates = []
        for paragraph in paragraphs:
            raw_text = paragraph.get("text") or ""
            text = " ".join(raw_text.split())
            if "unemployment rate" not in text.lower():
                continue

            sentences = sentence_split_re.split(text)
            best = None
            for sentence in sentences:
                score = score_sentence(sentence)
                if score < 0:
                    continue
                candidate = (score, len(sentence), sentence)
                if best is None or candidate[0] > best[0] or (
                    candidate[0] == best[0] and candidate[1] < best[1]
                ):
                    best = candidate
            if best is not None:
                paragraph_candidates.append((best[0], best[1], best[2], paragraph))
            elif month_re.search(text) and percent_re.search(text):
                paragraph_candidates.append((0, len(text), text, paragraph))

        if paragraph_candidates:
            paragraph_candidates.sort(key=lambda item: (-item[0], item[1]))
            add_span(paragraph_candidates[0][2], paragraph_candidates[0][3])
            return spans

        lines = doc.get("lines") or []
        for idx, line in enumerate(lines):
            raw_text = line.get("text") or ""
            text = " ".join(raw_text.split())
            low = text.lower()
            if "unemployment rate" not in low:
                continue
            if not month_re.search(low) or not percent_re.search(low):
                continue
            start = max(0, idx - 1)
            end = min(len(lines), idx + 3)
            combined = " ".join(
                " ".join(((lines[j].get("text") or "").split()))
                for j in range(start, end)
                if (lines[j].get("text") or "").strip()
            )
            if combined:
                add_span(combined, line)

        return spans
    except Exception:
        return []

